// encode/decode preserve integer precision and reject malformed JSON without partial output mutation.
template<class T> std::string encode(const T& value) { return dump(to_json(value)); }
template<class T> bool decode(std::string_view wire, T& value, std::string* error = nullptr) { try { T next{}; from_json(Parser(wire).parse(), next); value = std::move(next); return true; } catch(const std::exception& e) { if (error) *error=e.what(); return false; } }
